<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import {useRoute} from 'vue-router'
import {can,projectId} from '@/core/session'
import {ApiError,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import RuleSourceSetPicker from './RuleSourceSetPicker.vue'
import {sourceIds,type RuleSourceSelection} from './rule-source-selection'
import {readRuleSource,writeRuleSource,confirmRuleSource,sourceSelection,sourceContract,deviceSourceMembers,readRuleSourceNames as readNames,type RuleSourceSnapshot,type RuleDeviceSourceContract} from './rule-source-api'
const props=defineProps<{ruleId:string;definitionVersion:string;inactive?:boolean;refreshContext:(source:RuleDeviceSourceContract)=>Promise<void>}>()
const route=useRoute()
const emit=defineEmits<{busy:[value:boolean];locked:[value:boolean];denied:[cause:ApiError,uncertain:boolean]}>()
const data=shallowRef<RuleSourceSnapshot>(),names=ref<Map<string,string>>(new Map()),draft=shallowRef<RuleSourceSelection>(),editing=ref(false),busy=ref(false),selecting=ref(false),unknown=ref(false),conflict=ref(false),error=ref(''),authorityNotice=ref('')
const backgroundRead=ref(false)
const pending=shallowRef<{before:RuleSourceSnapshot;wanted:RuleDeviceSourceContract;accepted?:RuleSourceSnapshot}>()
const readAllowed=computed(()=>!!projectId.value&&(can('rule:read')||can('rule:manage'))),writeAllowed=computed(()=>!!projectId.value&&can('rule:manage')),blocked=computed(()=>!writeAllowed.value||!!props.inactive||busy.value||selecting.value||unknown.value||conflict.value)
const rows=computed(()=>data.value?deviceSourceMembers(data.value.deviceSource).map(referenceId=>({referenceId,name:names.value.get(referenceId)??'',href:{path:data.value!.deviceSource.kind==='DEVICE'?'/devices/'+referenceId:'/device-types/'+referenceId,query:{returnRule:route?.fullPath||`/rules/messages/${props.ruleId}`}}})):[])
let alive=true,turn=0,controller:AbortController|undefined
function clear(){turn++;controller?.abort();data.value=undefined;names.value=new Map();draft.value=undefined;editing.value=false;busy.value=false;selecting.value=false;unknown.value=false;conflict.value=false;error.value='';authorityNotice.value='';pending.value=undefined}
function capture(){const generation=turn,epoch=identityEpoch(),project=projectId.value,rule=props.ruleId;return{project,rule,current:()=>alive&&generation===turn&&epoch===identityEpoch()&&project===projectId.value&&rule===props.ruleId&&readAllowed.value}}
function denied(cause:unknown,uncertain=false){if(!(cause instanceof ApiError)||![401,403,404].includes(cause.status))return false;clear();error.value=(uncertain?'原来源保存结果未确认。':'')+errorMessage(cause);emit('denied',cause,uncertain);return true}

async function load(force=false,background=false){if(!readAllowed.value||busy.value||unknown.value||editing.value&&!force)return;const s=capture();controller?.abort();controller=new AbortController();backgroundRead.value=background;busy.value=true;error.value='';try{const value=await readRuleSource(s.project,s.rule,controller.signal);if(!s.current())return;if(!force&&value.definitionVersion!==props.definitionVersion)throw new Error('规则已变化，请读取最新来源');const labels=await readNames(s.project,value.deviceSource,controller.signal);if(!s.current())return;data.value=value;names.value=labels;draft.value=undefined;editing.value=false;conflict.value=false;pending.value=undefined}catch(cause){if(s.current()){if(background)data.value=undefined;error.value=errorMessage(cause);denied(cause)}}finally{if(s.current()){busy.value=false;backgroundRead.value=false}}}
watch([projectId,()=>props.ruleId,readAllowed],()=>{clear();if(readAllowed.value)void load()},{immediate:true})
watch(writeAllowed,(value,previous)=>{if(previous&&!value&&(editing.value||unknown.value||pending.value)){const uncertain=unknown.value||!!pending.value;clear();authorityNotice.value=(uncertain?'原来源保存结果未确认。':'')+'当前没有来源编辑权限';if(readAllowed.value)void load()}})
watch(()=>props.definitionVersion,()=>{if(!busy.value&&!editing.value&&!unknown.value)void load(false,true)})
watch(busy,value=>emit('busy',value&&!backgroundRead.value),{immediate:true,flush:'sync'});watch([editing,unknown,conflict],()=>emit('locked',editing.value||unknown.value||conflict.value),{immediate:true,flush:'sync'})
const dispose=onIdentityChange(clear);onScopeDispose(()=>{alive=false;controller?.abort();dispose();emit('busy',false);emit('locked',false)})
function edit(){if(blocked.value||!data.value||data.value.readOnly||data.value.deviceSource.kind==='LEGACY_PROJECT')return;draft.value=sourceSelection(data.value.deviceSource,names.value);editing.value=true;error.value=''}
function cancel(){if(blocked.value)return;draft.value=undefined;editing.value=false;error.value=''}
async function save(){const before=data.value;if(blocked.value||!before||!draft.value||!editing.value||before.readOnly)return;let wanted:RuleDeviceSourceContract;try{sourceIds(draft.value);wanted=sourceContract(draft.value)}catch(cause){error.value=errorMessage(cause);return}const s=capture();pending.value={before,wanted};busy.value=true;error.value='';authorityNotice.value='';try{const accepted=await writeRuleSource(s.project,before,wanted,s.current);if(!s.current())return;pending.value={before,wanted,accepted};confirmRuleSource(before,wanted,accepted);const actual=await readRuleSource(s.project,s.rule);if(!s.current())return;confirmRuleSource(before,wanted,actual,accepted);const labels=await readNames(s.project,actual.deviceSource);if(!s.current())return;data.value=actual;names.value=labels;await props.refreshContext(actual.deviceSource);if(!s.current())return;pending.value=undefined;draft.value=undefined;editing.value=false;}catch(cause){if(s.current()){error.value=errorMessage(cause);const rejected=!pending.value?.accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&cause.code!==10014&&[400,401,403,404,409,422].includes(cause.status);unknown.value=!rejected;if(rejected){pending.value=undefined;conflict.value=cause instanceof ApiError&&cause.status===409}denied(cause,unknown.value)}}finally{if(s.current())busy.value=false}}
async function recover(){const intent=pending.value;if(!intent||busy.value||!writeAllowed.value||data.value?.readOnly||props.inactive)return;const s=capture();busy.value=true;error.value='';try{const actual=await readRuleSource(s.project,s.rule);if(!s.current())return;confirmRuleSource(intent.before,intent.wanted,actual,intent.accepted);const labels=await readNames(s.project,actual.deviceSource);if(!s.current())return;data.value=actual;names.value=labels;await props.refreshContext(actual.deviceSource);if(!s.current())return;draft.value=undefined;pending.value=undefined;unknown.value=false;editing.value=false;}catch(cause){if(s.current()){error.value=errorMessage(cause);denied(cause,true)}}finally{if(s.current())busy.value=false}}
async function refreshConflict(){if(busy.value||unknown.value||props.inactive)return;await load(true);if(data.value&&!conflict.value)try{await props.refreshContext(data.value.deviceSource)}catch(cause){error.value=errorMessage(cause);conflict.value=true;editing.value=true}}
</script>
<template><div class="rule-source-inline"><div v-if="!editing" class="source-tags"><router-link v-for="row in rows" :key="row.referenceId" :to="row.href">{{row.name}}</router-link><el-button v-if="writeAllowed&&data&&!data.readOnly&&data.deviceSource.kind!=='LEGACY_PROJECT'" class="source-edit" size="small" :disabled="blocked" @click="edit">编辑</el-button></div><template v-else><RuleSourceSetPicker v-model="draft" :fixed-kind="data?.deviceSource.kind==='DEVICE_TYPE'?'DEVICE_TYPE':'DEVICE'" inline :disabled="blocked" @busy="selecting=$event" @denied="denied($event,unknown)"/><div class="source-edit-actions"><el-button v-if="!unknown&&!conflict" type="primary" size="small" :disabled="blocked||!draft" @click="save">保存</el-button><el-button v-if="!unknown&&!conflict" text size="small" :disabled="blocked" @click="cancel">取消</el-button><el-button v-if="unknown&&pending" size="small" :disabled="busy||inactive" @click="recover">读取原来源核对</el-button><el-button v-if="conflict" size="small" :disabled="busy||inactive" @click="refreshConflict">读取最新来源</el-button></div></template><p v-if="error" role="alert" class="source-error">{{unknown?'来源保存结果尚未确认，请勿重复提交。':conflict?'来源已变化，请读取最新来源后重新决定。':''}}{{error}}<el-button v-if="!editing&&!unknown" link :disabled="busy||inactive" @click="refreshConflict">重新读取来源</el-button></p><p v-if="authorityNotice" role="alert" class="source-error">{{authorityNotice}}</p></div></template>
<style scoped>.source-tags>a{display:inline-flex;align-items:center;justify-content:center;margin:0 5px 5px 0;padding:0 .75em;border:0;border-radius:4px;background:#f5f5f5;color:#1e88e5;font-size:12px;height:2em;line-height:1.5;white-space:nowrap;text-decoration:none}.source-edit{display:block;margin-top:5px}.source-edit-actions{display:flex;align-items:center;gap:10px;margin-top:10px}.source-edit-actions .el-button+.el-button{margin-left:0}.source-error{font-size:13px;line-height:18px;color:var(--el-color-danger);margin:8px 0}</style>
